// Every row is a separate situation, not a turn that requires earlier items.
const lesson=(id,level,title,subtitle,rule,rows)=>({
  id,level,kind:'conversation',roleplay:true,color:'blue',icon:'chat',title,subtitle,rule,
  items:rows.map(([da,ru,note,situation,partnerDa,partnerRu,goal,alternative],index)=>({
    id:`${id}-${index+1}`,lessonId:id,da,ru,note,
    daAnswers:[da,alternative],ruAnswers:[ru],wordClass:'phrase',
    dialogue:{situation,partnerDa,partnerRu,goal}
  }))
});

